files.content:
.steezy-pattern-shell {
  --bg: #ff6f61;
  --ink: #121212;
  --shadow: #7f2a20;
  background: var(--bg);
  border-radius: 1rem;
  padding: 1rem;
  width: 100%;
}

.steezy-pattern-grid {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  color: var(--ink);
}

.steezy-pattern-title {
  margin: 0;
  grid-column: 1 / -1;
  font-size: 1.75rem;
  line-height: 1.1;
  letter-spacing: 0.01em;
}

.steezy-pattern-description {
  margin: 0;
  grid-column: 1 / -1;
  font-size: 0.95rem;
  line-height: 1.45;
}

.steezy-card {
  border-radius: 0.5rem;
  border: 2px solid var(--ink);
  background: #fff;
  box-shadow: 0.35rem 0.35rem 0 var(--shadow), 0.35rem 0.35rem 0 2px var(--ink);
  min-height: 3rem;
  padding: 0.85rem 0.75rem;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  font-weight: 700;
  transition: transform 160ms ease, box-shadow 160ms ease;
}

.steezy-card:active {
  transform: translate(0.35rem, 0.35rem);
  box-shadow: 0 0 0 var(--shadow), 0 0 0 2px var(--ink);
}

.steezy-pattern-art {
  grid-column: 1 / -1;
  min-height: 7rem;
  background:
    repeating-linear-gradient(
      45deg,
      #ffffff 10px,
      transparent 11px,
      transparent 15px,
      #ffffff 16px,
      #ffffff 20px
    ),
    repeating-linear-gradient(
      -45deg,
      #121212 10px,
      transparent 11px,
      transparent 15px,
      #121212 16px,
      #121212 20px
    ),
    #ffffff;
}

.steezy-pattern-big {
  grid-column: 1 / -1;
  font-size: 1.1rem;
  font-style: italic;
  gap: 0.35rem;
}

.steezy-pattern-big a {
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 0.18em;
}

.steezy-skill-2 {
  background: #ffe44d;
}

.steezy-skill-3 {
  background: #812a97;
  color: #fff;
}

.steezy-skill-4 {
  background: #cb0000;
  color: #fff;
}

.steezy-skill-6 {
  background: #f48217;
}

.steezy-skill-7 {
  background: #389ad6;
  color: #fff;
}

.steezy-skill-8 {
  background: #e34c27;
}

.steezy-pattern-subtitle {
  margin: 0.25rem 0 0;
  grid-column: 1 / -1;
  font-size: 1.5rem;
  line-height: 1.05;
  text-transform: lowercase;
}

.steezy-social {
  text-decoration: none;
  color: inherit;
}

@media (min-width: 900px) {
  .steezy-pattern-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .steezy-pattern-description {
    grid-column: 1 / 3;
  }

  .steezy-pattern-art {
    grid-column: 3 / 5;
    min-height: 9rem;
  }

  .steezy-pattern-big {
    grid-column: 1 / 5;
  }

  .steezy-pattern-subtitle {
    margin-top: 0.5rem;
  }

  .steezy-social-2 {
    grid-column: 2 / 4;
  }

  .steezy-social-5 {
    grid-column: 3 / 5;
  }
}
